// Some portions generated by Claude
import assert from 'node:assert/strict';
import test from 'node:test';
import { canvasGraph } from '../../../main/frontend/graph-explorer/graph-canvas-scope.ts';
import { graphNodeSize } from '../../../main/frontend/graph-explorer/graph-geometry.ts';
import { computeGraphLayout } from '../../../main/frontend/graph-explorer/graph-layout-engine.ts';
import { computeNetworkLayout } from '../../../main/frontend/graph-explorer/graph-layout-network.ts';
import { peelSatellites, similaritySprings } from '../../../main/frontend/graph-explorer/graph-layout-satellites.ts';
import { demoGraph, iri } from './fixtures/layout-demo-graph.mjs';
import { conferenceHub, geoTree } from './fixtures/layout-shapes.mjs';
import { layoutMetrics } from './support/benchmark-layout.mjs';

const degrees = (radians) => (radians * 180) / Math.PI;
function neighborhood(graph, positions, id) {
  const degree = new Map();
  graph.edges.forEach((edge) => { degree.set(edge.source, (degree.get(edge.source) ?? 0) + 1); degree.set(edge.target, (degree.get(edge.target) ?? 0) + 1); });
  const center = positions.get(id);
  const around = graph.edges.flatMap((edge) => (edge.source === id ? [edge.target] : edge.target === id ? [edge.source] : []));
  const describe = (other) => { const p = positions.get(other); return { id: other, angle: Math.atan2(p.y - center.y, p.x - center.x), distance: Math.hypot(p.x - center.x, p.y - center.y) }; };
  return { leaves: around.filter((other) => degree.get(other) === 1).map(describe), hubs: around.filter((other) => degree.get(other) > 1).map(describe) };
}
const angularDistance = (a, b) => { const d = Math.abs(a - b) % (Math.PI * 2); return Math.min(d, Math.PI * 2 - d); };
/** Smallest arc that contains every angle, in degrees. */
function sectorSpan(angles) {
  const sorted = angles.map((a) => ((a % (Math.PI * 2)) + Math.PI * 2) % (Math.PI * 2)).sort((a, b) => a - b);
  let widestGap = 0;
  sorted.forEach((a, i) => { const next = i + 1 < sorted.length ? sorted[i + 1] : sorted[0] + Math.PI * 2; widestGap = Math.max(widestGap, next - a); });
  return degrees(Math.PI * 2 - widestGap);
}

test('organize keeps hubs apart and fans each hub\'s satellites on the side away from its skeleton neighbours', async () => {
  const graph = demoGraph();
  const result = await computeGraphLayout(graph, { mode: 'network', aspectRatio: 1.6 });
  const metrics = layoutMetrics(graph, result.positions);
  assert.equal(metrics.nodeOverlaps, 0);
  assert.equal(metrics.edgeCrossings, 0, `crossings: ${metrics.edgeCrossings}`);
  // Acme's satellites: its label, its class and its three products (each product carries its own label).
  const acme = neighborhood(graph, result.positions, iri('Acme'));
  const satellites = acme.leaves.concat(acme.hubs.filter((h) => ['Widget', 'Gadget', 'Gizmo'].some((p) => h.id === iri(p))));
  const skeleton = acme.hubs.filter((h) => !satellites.includes(h));
  assert.deepEqual(skeleton.map((h) => h.id).sort(), [iri('Alice'), iri('Bob'), iri('Oslo')].sort());
  for (const s of satellites) for (const h of skeleton) {
    assert.ok(degrees(angularDistance(s.angle, h.angle)) >= 30, `${s.id} is only ${degrees(angularDistance(s.angle, h.angle)).toFixed(0)}° from ${h.id}`);
  }
  assert.ok(sectorSpan(satellites.map((s) => s.angle)) <= 200, `Acme's satellites span ${sectorSpan(satellites.map((s) => s.angle)).toFixed(0)}°`);
  const longestSpoke = Math.max(...satellites.map((s) => s.distance));
  for (const h of skeleton) assert.ok(h.distance >= 1.3 * longestSpoke, `Acme–${h.id} ${h.distance.toFixed(0)} < 1.3 × spoke ${longestSpoke.toFixed(0)}`);
  // Products sit next to each other: no other satellite lies between them on the arc.
  const ordered = satellites.slice().sort((a, b) => a.angle - b.angle).map((s) => s.id);
  const productIndexes = ['Widget', 'Gadget', 'Gizmo'].map((p) => ordered.indexOf(iri(p))).sort((a, b) => a - b);
  const contiguous = productIndexes[2] - productIndexes[0] === 2 || (productIndexes[0] === 0 && productIndexes[2] === ordered.length - 1 && (productIndexes[1] === 1 || productIndexes[1] === ordered.length - 2));
  assert.ok(contiguous, `products at ${productIndexes} of ${ordered.length}`);
  const oslo = neighborhood(graph, result.positions, iri('Oslo'));
  for (const s of oslo.leaves) for (const h of oslo.hubs.filter((h) => h.id !== iri('Norway'))) {
    assert.ok(degrees(angularDistance(s.angle, h.angle)) >= 30, `${s.id} is only ${degrees(angularDistance(s.angle, h.angle)).toFixed(0)}° from ${h.id}`);
  }
});

test('satellite fans are deterministic', async () => {
  const first = await computeGraphLayout(demoGraph(), { mode: 'network', aspectRatio: 1.6 });
  const second = await computeGraphLayout(demoGraph(), { mode: 'network', aspectRatio: 1.6 });
  assert.deepEqual(first.positions, second.positions);
});

test('with Values off the products, Dave and Norway are satellites and the people stay together', async () => {
  const graph = canvasGraph(demoGraph(), false);
  const peeled = peelSatellites(graph, {});
  assert.deepEqual([...peeled.anchorOf.keys()].sort(), ['Dave', 'Gadget', 'Gizmo', 'Norway', 'Widget'].map(iri).sort());
  assert.equal(peeled.anchorOf.get(iri('Dave')), iri('Bob'));
  const result = await computeGraphLayout(graph, { mode: 'network', aspectRatio: 1.6 });
  const p = (name) => result.positions.get(iri(name));
  for (const [a, b] of [['Alice', 'Bob'], ['Alice', 'Carol']]) {
    assert.ok(Math.hypot(p(a).x - p(b).x, p(a).y - p(b).y) <= 260, `${a}–${b} too far apart`);
  }
  assert.equal(layoutMetrics(graph, result.positions).edgeCrossings, 0);
});

test('a small star is fanned on a full circle without overlaps', async () => {
  const nodes = Array.from({ length: 8 }, (_, i) => ({ id: `n${i}`, label: `Node ${i}`, kind: 'iri', x: 0, y: 0 }));
  const edges = nodes.slice(1).map((node) => ({ id: `e${node.id}`, source: 'n0', target: node.id, predicate: 'urn:p', label: 'p' }));
  const graph = { nodes, edges, revision: 1 };
  const result = await computeGraphLayout(graph, { mode: 'network' });
  assert.equal(layoutMetrics(graph, result.positions).nodeOverlaps, 0);
  const hub = neighborhood(graph, result.positions, 'n0');
  const radii = hub.leaves.map((leaf) => leaf.distance);
  assert.ok(Math.max(...radii) <= 1.5 * Math.min(...radii), `uneven radii ${radii.map((r) => r.toFixed(0))}`);
  assert.ok(sectorSpan(hub.leaves.map((leaf) => leaf.angle)) >= 300, 'leaves should surround the hub');
});

test('peeling is off for incremental, repair-only, named-group and pure-star layouts', () => {
  const graph = canvasGraph(demoGraph(), false);
  for (const options of [{ incremental: true, movableNodeIds: new Set([iri('Dave')]) }, { repairOnly: true }, { groups: [{ id: 'g', nodeIds: [iri('Alice')] }] }]) {
    assert.equal(peelSatellites(graph, options).anchorOf.size, 0, JSON.stringify(Object.keys(options)));
  }
  const star = { revision: 1, nodes: Array.from({ length: 21 }, (_, i) => ({ id: `s${i}`, label: `s${i}`, kind: 'iri' })),
    edges: Array.from({ length: 20 }, (_, i) => ({ id: `e${i}`, source: 's0', target: `s${i + 1}`, predicate: 'urn:p', label: 'p' })) };
  assert.equal(peelSatellites(star, {}).anchorOf.size, 0, 'pure stars keep the sunflower layout');
  const pinned = { ...graph, nodes: graph.nodes.map((node) => (node.id === iri('Dave') ? { ...node, pinned: true } : node)) };
  assert.ok(!peelSatellites(pinned, {}).anchorOf.has(iri('Dave')), 'a pinned leaf is never a satellite');
});

test('same-typed nodes that share a neighbour are pulled together by similarity springs when that costs no crossings', async () => {
  // Two researchers (same class) with no link between them share one university and have one of their own; a third
  // researcher of the same class shares nothing with them.
  const person = (id, x) => ({ id, label: id, kind: 'iri', types: [{ id: 'urn:Person', label: 'Person' }], x, y: 0 });
  const uni = (id, x, y) => ({ id, label: `University ${id}`, kind: 'iri', x, y });
  const nodes = [person('p1', -200), person('p2', 200), person('p3', 600), uni('u1', 0, -200), uni('u2', -400, 0), uni('u3', 400, 0), uni('u4', 800, -200), uni('u5', 800, 200)];
  // Cycles keep every node in the skeleton (nothing is a leaf): p1-u1-p2-u3-u2-p1 and p3-u4-u5-p3, joined by u3-u4.
  const edges = [['p1', 'u1'], ['p2', 'u1'], ['p1', 'u2'], ['p2', 'u3'], ['u2', 'u3'], ['p3', 'u4'], ['p3', 'u5'], ['u4', 'u5'], ['u3', 'u4']]
    .map(([a, b]) => ({ id: `${a}-${b}`, source: a, target: b, predicate: 'urn:educatedAt', label: 'educated at' }));
  const graph = { nodes, edges, revision: 1 };
  const springs = similaritySprings(graph, peelSatellites(graph, {}));
  assert.deepEqual(springs.map((s) => [s.source, s.target].sort().join('+')), ['p1+p2']);
  const plain = computeNetworkLayout(graph, { seed: 42 }).positions;
  const sprung = computeNetworkLayout(graph, { seed: 42, springs }).positions;
  const distance = (positions) => Math.hypot(positions.get('p1').x - positions.get('p2').x, positions.get('p1').y - positions.get('p2').y);
  assert.ok(distance(sprung) < distance(plain) * 0.8, `springs: ${distance(sprung).toFixed(0)} vs plain ${distance(plain).toFixed(0)}`);
  const result = await computeGraphLayout(graph, { mode: 'network' });
  assert.ok(layoutMetrics(graph, result.positions).edgeCrossings <= layoutMetrics(graph, plain).edgeCrossings);
  assert.ok(distance(result.positions) < distance(plain) * 0.8, `organize keeps the similar researchers together: ${distance(result.positions).toFixed(0)} vs plain ${distance(plain).toFixed(0)}`);
});

test('type links to a class with many instances do not stop instances from being satellites', async () => {
  const graph = canvasGraph(geoTree(5, 4, 3, { values: true }), true);
  const RDF_TYPE = 'http://www.w3.org/1999/02/22-rdf-syntax-ns#type';
  const peeled = peelSatellites(graph, {});
  const skeleton = peeled.skeleton.nodes.map((node) => node.label).sort();
  assert.deepEqual(skeleton, ['City', 'District', 'Norway', 'Region', 'Region 1', 'Region 2', 'Region 3', 'Region 4', 'Region 5'], skeleton.join(', '));
  const result = await computeGraphLayout(graph, { mode: 'network', aspectRatio: 1.6 });
  const withoutTypes = { ...graph, edges: graph.edges.filter((edge) => edge.predicate !== RDF_TYPE) };
  const metrics = layoutMetrics(withoutTypes, result.positions);
  assert.equal(metrics.nodeOverlaps, 0);
  assert.equal(metrics.edgeNodeOverlaps, 0, `tree edges through cards: ${metrics.edgeNodeOverlaps}`);
  assert.ok(metrics.edgeCrossings <= 2, `tree crossings: ${metrics.edgeCrossings}`);
  // A class with many instances sits among them, not far away.
  const byId = new Map(graph.nodes.map((node) => [node.id, node]));
  const districtClass = graph.nodes.find((node) => node.label === 'District');
  const districts = graph.edges.filter((edge) => edge.predicate === RDF_TYPE && edge.target === districtClass.id).map((edge) => result.positions.get(edge.source));
  const centroid = { x: districts.reduce((sum, p) => sum + p.x, 0) / districts.length, y: districts.reduce((sum, p) => sum + p.y, 0) / districts.length };
  const classPosition = result.positions.get(districtClass.id);
  const spread = Math.max(...districts.map((p) => Math.hypot(p.x - centroid.x, p.y - centroid.y)));
  assert.ok(Math.hypot(classPosition.x - centroid.x, classPosition.y - centroid.y) < spread * 0.5, 'the District class is placed among the districts');
  void byId;
});

